begin;
create table if not exists workshop_private.catalog75_rev(section text primary key,rev integer not null);
create table if not exists workshop_private.catalog75(id uuid primary key default gen_random_uuid(),section text not null references workshop_private.catalog75_rev,name text not null,photo bytea,position integer not null);
create unique index if not exists catalog75_name on workshop_private.catalog75(section,lower(trim(name)));
alter table workshop_private.catalog75 enable row level security;alter table workshop_private.catalog75_rev enable row level security;
revoke all on workshop_private.catalog75,workshop_private.catalog75_rev from public,anon,authenticated;
do $$ declare images jsonb;begin
if not exists(select 1 from workshop_private.catalog75_rev where section='Pneus') then
images:=$imgs${"/pneus74/p7-0.webp": "", "/pneus74/p5-10.webp": "", "/pneus74/p5-7.webp": "", "/pneus74/p4-3.webp": "", "/pneus74/p6-1.webp": "", "/pneus74/p5-6.webp": "", "/pneus74/p7-6.webp": "", "/pneus74/p4-0.webp": "", "/pneus74/p5-0.webp": "", "/pneus74/p4-11.webp": "", "/pneus74/p7-5.webp": "", "/pneus74/p1-3.webp": "", "/pneus74/p3-11.webp": "", "/pneus74/p2-1.webp": "", "/pneus74/p4-12.webp": "", "/pneus74/p2-0.webp": "", "/pneus74/p4-6.webp": "", "/pneus74/p1-9.webp": "", "/pneus74/p4-5.webp": "", "/pneus74/p4-10.webp": "", "/pneus74/p7-7.webp": "", "/pneus74/p1-7.webp": "", "/pneus74/p1-1.webp": "", "/pneus74/p1-6.webp": "", "/pneus74/p1-8.webp": "", "/pneus74/p1-5.webp": "", "/pneus74/p6-2.webp": "", "/pneus74/p7-8.webp": "", "/pneus74/p6-8.webp": "UklGRoQAAABXRUJQVlA4IHgAAAAQCgCdASo2AVkAPkUij0YioiEhIEgAUAiJaW7hdgEe3AfgAAAnteirhBkENVSa7bRcIMghqqTXbaLhBkENVSa7bRcIMghqqTXbaLhBkENVSa7bRcIMghqpsAD+/1Zgf//n5nduL+q3//+wz/rzL68y/7BYAAAAAAA=", "/pneus74/p4-9.webp": "", "/pneus74/p7-2.webp": "", "/pneus74/p5-2.webp": "", "/pneus74/p7-1.webp": "", "/pneus74/p4-8.webp": "", "/pneus74/p5-9.webp": "", "/pneus74/p6-4.webp": "", "/pneus74/p2-2.webp": "", "/pneus74/p6-3.webp": "", "/pneus74/p5-1.webp": "", "/pneus74/p1-2.webp": "", "/pneus74/p3-10.webp": "", "/pneus74/p2-4.webp": "", "/pneus74/p3-4.webp": "", "/pneus74/p1-0.webp": "", "/pneus74/p2-8.webp": "", "/pneus74/p6-0.webp": "", "/pneus74/p4-4.webp": "", "/pneus74/p4-7.webp": "", "/pneus74/p6-5.webp": "", "/pneus74/p5-3.webp": "", "/pneus74/p5-8.webp": "", "/pneus74/p1-4.webp": "", "/pneus74/p3-0.webp": "", "/pneus74/p1-12.webp": "", "/pneus74/p3-7.webp": "", "/pneus74/p2-3.webp": "", "/pneus74/p6-9.webp": ""}$imgs$::jsonb;
insert into workshop_private.catalog75_rev values('Pneus',1);
insert into workshop_private.catalog75(section,name,photo,position) select 'Pneus',v->>'name',decode(images->>(v->>'photo'),'base64'),ord from workshop_private.tyres74 t cross join lateral jsonb_array_elements(t.names) with ordinality as a(v,ord);
-- MAJ74 conservait uniquement la désignation dans les commandes. Rattacher les correspondances exactes non ambiguës.
update public.workshop_order_requests o set items=(select jsonb_agg(case when c.id is null then x else x||jsonb_build_object('id',c.id) end order by ord) from jsonb_array_elements(o.items) with ordinality as t(x,ord) left join workshop_private.catalog75 c on c.section='Pneus' and lower(trim(c.name))=lower(trim(x->>'label'))),version=version+1 where exists(select 1 from jsonb_array_elements(o.items) x join workshop_private.catalog75 c on c.section='Pneus' and lower(trim(c.name))=lower(trim(x->>'label')) ) and not exists(select 1 from jsonb_array_elements(o.items) x group by lower(trim(x->>'label')) having count(*)>1);
end if;
if not exists(select 1 from workshop_private.catalog75_rev where section='5gaz') then
insert into workshop_private.catalog75_rev values('5gaz',1);
insert into workshop_private.catalog75(section,name,photo,position) select '5gaz',v->>'name',decode(v->>'photo','base64'),ord from jsonb_array_elements($gaz$[{"name": "10 FILTRES A PARTICULES 2 MICRONS", "photo": ""}, {"name": "10 FILTRES A CONDENSATS 25 MICRONS", "photo": ""}, {"name": "5 FILTRES A PARTICULES 0,1 MICRON", "photo": ""}, {"name": "10 FILTRES A CONDENSATS", "photo": ""}, {"name": "NETTOYANT SYSTEME ESSENCE 5L", "photo": ""}, {"name": "NET.SYSTEME DIESEL 5L", "photo": ""}, {"name": "NET.FAP/TURBO 5L", "photo": ""}, {"name": "NETTOYANT HUILE MOTEUR 5L", "photo": ""}, {"name": "DIESEL AIR CLEANER 5L", "photo": ""}, {"name": "DEGOMMANT MOTEUR", "photo": ""}, {"name": "MOUSSE EXPANSIVE NETTOYANTE (Pour la prestation de nettoyage de l'admission avec la nouvelle machine)", "photo": ""}, {"name": "NETTOYANT INJECTION DIESEL 5L (POUR NETTOYAGE PREVENTIF ET CURATIF)", "photo": ""}, {"name": "NETTOYANT INJECTION ESSENCE 5L (POUR NETTOYAGE PREVENTIF ET CURATIF)", "photo": ""}]$gaz$::jsonb) with ordinality as a(v,ord);
end if;end $$;
drop function if exists public.workshop_tyres74(jsonb,integer);
drop table if exists workshop_private.tyres74;
create or replace function public.workshop_catalog75(p_section text,p_known integer default -1) returns jsonb language plpgsql security definer set search_path='' as $$
declare v integer;begin perform workshop_private.actor_before30();select rev into strict v from workshop_private.catalog75_rev where section=p_section;
return jsonb_build_object('rev',v,'items',case when p_known<>v then (select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'photo',case when photo is null then '' else 'data:image/webp;base64,'||replace(encode(photo,'base64'),chr(10),'') end) order by position,id),'[]') from workshop_private.catalog75 where section=p_section) end);end $$;
create or replace function public.workshop_catalog_change75(p_section text,p_rev int,p_action text,p_id uuid,p_name text default '') returns void language plpgsql security definer set search_path='' as $$
declare a jsonb;v int;r workshop_private.catalog75%rowtype;begin a:=workshop_private.actor();
if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur';end if;
select rev into strict v from workshop_private.catalog75_rev where section=p_section for update;
if v is distinct from p_rev then raise exception 'Catalogue modifié : ferme puis rouvre l’éditeur.';end if;
if p_action in ('add','rename') and length(trim(coalesce(p_name,''))) not between 1 and 200 then raise exception 'Nom invalide';end if;
if p_action='add' then insert into workshop_private.catalog75(section,name,position) select p_section,trim(p_name),coalesce(max(position),0)+1 from workshop_private.catalog75 where section=p_section;
else select * into strict r from workshop_private.catalog75 where section=p_section and id=p_id for update;
if p_action='delete' then
update public.workshop_order_requests o set items=(select coalesce(jsonb_agg(x order by ord),'[]') from jsonb_array_elements(o.items) with ordinality as t(x,ord) where (x->>'id') is distinct from r.id::text),version=o.version+1,updated_at=now() where exists(select 1 from jsonb_array_elements(o.items) x where x->>'id'=r.id::text);
delete from workshop_private.catalog75 where id=r.id;
elsif p_action='rename' then update workshop_private.catalog75 set name=trim(p_name) where id=r.id;
else raise exception 'Action inconnue';end if;end if;
update workshop_private.catalog75_rev set rev=rev+1 where section=p_section;end $$;
revoke all on function public.workshop_catalog75(text,integer),public.workshop_catalog_change75(text,integer,text,uuid,text) from public,anon;
grant execute on function public.workshop_catalog75(text,integer),public.workshop_catalog_change75(text,integer,text,uuid,text) to authenticated;
notify pgrst,'reload schema';commit;
